using SoulsFormats;using System.Security.Cryptography;using System.Text.Json;
internal static class SourceObjectTexturesTests {
    static string Leaf(string p)=>Path.GetFileName(p.Replace('\\','/'));
    static string Name(string p)=>Leaf(p).Split('.')[0];
    static void Need(bool value,string why){if(!value)throw new InvalidDataException(why);}
    static void Main(string[] args){string root=args[0],output="out/map-editor/source-object-textures";Directory.CreateDirectory(output);var hashes=new Dictionary<string,string>();var reads=new List<string>();byte[]? Read(string path){reads.Add(path);string file=Path.Combine(root,path);if(!File.Exists(file))return null;var bytes=File.ReadAllBytes(file);string hash=Convert.ToHexString(SHA256.HashData(bytes));Need(!hashes.TryGetValue(file,out var previous)||previous==hash,"Original changed during fixture");hashes.TryAdd(file,hash);return bytes;}
        var statue=BND3.Read(Read("obj/o3321.objbnd.dcx")!);var model=FLVER2.Read(statue.Files.Single(f=>Leaf(f.Name)=="o3321.flver").Bytes);var local=statue.Files.Where(f=>Leaf(f.Name).EndsWith(".tpf",StringComparison.OrdinalIgnoreCase)).SelectMany(f=>TPF.Read(f.Bytes).Textures).ToDictionary(t=>Name(t.Name),StringComparer.OrdinalIgnoreCase);var paths=model.Materials.SelectMany(m=>m.Textures).Select(t=>t.Path).Where(p=>!string.IsNullOrEmpty(p)).ToArray();var missing=paths.Where(p=>!local.ContainsKey(Name(p))).ToArray();Need(missing.Length==3&&local.ContainsKey("o3321_lit"),"Source statue's actual sibling-texture contract changed");
        reads.Clear();var resolved=SourceObjectTextures.Resolve(missing,Read);Need(resolved.Owners.SequenceEqual(new[]{"o3320"})&&resolved.Unresolved.Count==0&&resolved.Textures.Keys.Order().SequenceEqual(new[]{"o3320","o3320_n","o3320_s"}),"Actual o3321 -> o3320 closure failed");Need(reads.SequenceEqual(new[]{"obj/o3320.objbnd.dcx"}),"Resolver traversed an undeclared owner");var owner=BND3.Read(Read("obj/o3320.objbnd.dcx")!);var tpfFile=owner.Files.Single(f=>Leaf(f.Name).EndsWith(".tpf",StringComparison.OrdinalIgnoreCase));var ownerTpf=TPF.Read(tpfFile.Bytes);foreach(var(name,t)in resolved.Textures)Need(t.Bytes.SequenceEqual(ownerTpf.Textures.Single(t=>Name(t.Name)==name).Bytes),"Source texture payload changed");Need(paths.All(p=>local.ContainsKey(Name(p))||resolved.Textures.ContainsKey(Name(p))),"Actual statue still requires a fallback");
        var reversed=SourceObjectTextures.Resolve(missing.Reverse(),Read);Need(resolved.Textures.All(p=>reversed.Textures[p.Key].Bytes.SequenceEqual(p.Value.Bytes)),"Resolution depends on import/reference order");reads.Clear();var unowned=SourceObjectTextures.Resolve([@"N:\FRPG\data\Model\obj\o3310\tex\o3320.tga"],Read);Need(unowned.Textures.Count==0&&unowned.Unresolved.Count==1&&reads.All(p=>p.Contains("o3310",StringComparison.Ordinal)),"Resolver searched undeclared sibling/basename assets");
        byte[] Virtual(string id,string? next,string? second=null,string? texture=null) {var b=BND3.Read(owner.Write());b.Files.RemoveAll(f=>Leaf(f.Name).EndsWith(".tpf",StringComparison.OrdinalIgnoreCase));var entry=b.Files.Single(f=>Leaf(f.Name)=="o3320.flver");entry.Name=entry.Name.Replace("o3320",id,StringComparison.Ordinal);var f=FLVER2.Read(entry.Bytes);foreach(var material in f.Materials)material.Textures.Clear();if(next!=null)f.Materials[0].Textures.Add(new("g_Diffuse",@"N:\FRPG\data\Model\obj\"+next+@"\tex\shared.tga",System.Numerics.Vector2.One,0,0,0,0,0));if(second!=null)f.Materials[0].Textures.Add(new("g_Bumpmap",@"N:\FRPG\data\Model\obj\"+second+@"\tex\shared.tga",System.Numerics.Vector2.One,0,0,0,0,0));entry.Bytes=f.Write();if(texture!=null){var tpf=TPF.Read(tpfFile.Bytes);tpf.Textures.RemoveAll(t=>t.Name!=texture);Need(tpf.Textures.Count==1,"Virtual fixture source texture missing");tpf.Textures[0].Name="shared";b.Files.Add(new(tpfFile.Flags,tpfFile.ID,tpfFile.Name,tpf.Write()));}return b.Write();}
        void Rejected(Dictionary<string,byte[]> files,string reason){bool rejected=false;try{SourceObjectTextures.Resolve([@"N:\FRPG\data\Model\obj\o8000\tex\shared.tga"],p=>files.GetValueOrDefault(p));}catch(InvalidDataException e){rejected=e.Message.Contains(reason,StringComparison.Ordinal);}Need(rejected,"Missing traversal guard "+reason);}
        Rejected(new(){{"obj/o8000.objbnd.dcx",Virtual("o8000","o8001")},{"obj/o8001.objbnd.dcx",Virtual("o8001","o8000")}},"cycle");var deep=new Dictionary<string,byte[]>();for(int i=0;i<=SourceObjectTextures.MaximumDepth;i++)deep.Add("obj/o"+(8000+i)+".objbnd.dcx",Virtual("o"+(8000+i),"o"+(8001+i)));Rejected(deep,"depth");Rejected(new(){{"obj/o8000.objbnd.dcx",Virtual("o8000","o8001","o8002")},{"obj/o8001.objbnd.dcx",Virtual("o8001",null,texture:"o3320")},{"obj/o8002.objbnd.dcx",Virtual("o8002",null,texture:"o3320_n")}},"ambiguous");
        foreach(var(path,sha)in hashes)Need(Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(path)))==sha,"Original changed after fixture");File.WriteAllText(Path.Combine(output,"evidence.json"),JsonSerializer.Serialize(new{SourceModel="o3321",References=paths,Local=local.Keys,MissingBefore=missing,Owners=resolved.Owners,Resolved=resolved.Textures.Select(p=>new{Name=p.Key,Format=p.Value.Format,Bytes=p.Value.Bytes.Length,SHA=Convert.ToHexString(SHA256.HashData(p.Value.Bytes))}),Unresolved=resolved.Unresolved,OriginalHashes=hashes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS actual o3321 -> o3320: 3 authored textures restored, local lightmap retained, exact payload/order/owner guards; cycle/depth/ambiguity rejected; "+hashes.Count+" originals unchanged. No native export/gameplay claimed.");
    }
}
